@import "@fontsource/ibm-plex-serif/400.css";
@import "@fontsource/ibm-plex-serif/500.css";
@import "@fontsource-variable/inter";
@import "@fontsource-variable/jetbrains-mono";

/* Light: a sibling in the same spirit, warm lilac-grey paper, ink-violet text, the same
   violet primary, green and copper accents. */
:root {
  --background: oklch(0.975 0.004 300);
  --foreground: oklch(0.2 0.022 292);
  --card: oklch(0.94 0.008 296);
  --card-foreground: oklch(0.2 0.022 292);
  --popover: oklch(0.99 0.002 300);
  --popover-foreground: oklch(0.2 0.022 292);
  --primary: oklch(0.47 0.12 296);
  --primary-foreground: oklch(0.985 0.002 300);
  --secondary: oklch(0.2 0.022 292);
  --secondary-foreground: oklch(0.975 0.004 300);
  --muted: oklch(0.915 0.01 295);
  --muted-foreground: oklch(0.48 0.02 292);
  --accent: oklch(0.93 0.012 296);
  --accent-foreground: oklch(0.2 0.022 292);
  --destructive: oklch(0.58 0.21 25);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.2 0.022 292 / 11%);
  --input: oklch(0.2 0.022 292 / 18%);
  --ring: oklch(0.56 0.17 309);
  --highlight: oklch(0.6 0.17 346);
  --highlight-foreground: oklch(0.985 0 0);
  --glow: oklch(0.56 0.24 328);
  --chart-1: oklch(0.5 0.24 289);
  --chart-2: oklch(0.52 0.1 161);
  --chart-3: oklch(0.62 0.16 55);
  --chart-4: oklch(0.6 0.17 346);
  --chart-5: oklch(0.5 0.1 262);
  --sidebar: oklch(0.96 0.005 300);
  --sidebar-foreground: oklch(0.2 0.022 292);
  --sidebar-primary: oklch(0.47 0.12 296);
  --sidebar-primary-foreground: oklch(0.985 0.002 300);
  --sidebar-accent: oklch(0.93 0.012 296);
  --sidebar-accent-foreground: oklch(0.2 0.022 292);
  --sidebar-border: oklch(0.2 0.022 292 / 11%);
  --sidebar-ring: oklch(0.56 0.17 309);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "IBM Plex Serif", Georgia, "Times New Roman", serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 72.5rem;
  --page-gutter: 1rem;
  --section-y: 4rem;
}

/* Dark (faithful): the #13111c ink-violet page, #f7f7f8 text, lavender-grey secondary text,
   near-black windows, a muted violet button, sea green, copper, pink mentions, magenta glow. */
.dark {
  --background: oklch(0.186 0.022 292);
  --foreground: oklch(0.976 0.001 286);
  --card: oklch(0.227 0.027 291);
  --card-foreground: oklch(0.976 0.001 286);
  --popover: oklch(0.227 0.027 291);
  --popover-foreground: oklch(0.976 0.001 286);
  --primary: oklch(0.425 0.11 296);
  --primary-foreground: oklch(0.976 0.001 286);
  --secondary: oklch(0.152 0.009 285);
  --secondary-foreground: oklch(0.976 0.001 286);
  --muted: oklch(0.16 0.017 290);
  --muted-foreground: oklch(0.71 0.016 290);
  --accent: oklch(0.227 0.027 291);
  --accent-foreground: oklch(0.976 0.001 286);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(0.976 0.001 286);
  --border: oklch(1 0 0 / 9%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.606 0.173 309);
  --highlight: oklch(0.823 0.11 346);
  --highlight-foreground: oklch(0.186 0.022 292);
  --glow: oklch(0.52 0.235 328);
  --chart-1: oklch(0.492 0.245 289);
  --chart-2: oklch(0.605 0.1 161);
  --chart-3: oklch(0.717 0.158 55);
  --chart-4: oklch(0.823 0.11 346);
  --chart-5: oklch(0.53 0.1 262);
  --sidebar: oklch(0.16 0.017 290);
  --sidebar-foreground: oklch(0.976 0.001 286);
  --sidebar-primary: oklch(0.425 0.11 296);
  --sidebar-primary-foreground: oklch(0.976 0.001 286);
  --sidebar-accent: oklch(0.227 0.027 291);
  --sidebar-accent-foreground: oklch(0.976 0.001 286);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.606 0.173 309);
}
